import{_ as e,a}from"./chunks/stairs-grating.CT4n5VG8.js";import{_ as i,o as s,c as r,a5 as d}from"./chunks/framework.BYXPg_yw.js";const b=JSON.parse('{"title":"Stairs and Steps","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/stairs.md","filePath":"manual/operation/stairs.md","lastUpdated":1792759058000}'),o={name:"manual/operation/stairs.md"};function n(h,t,l,c,g,p){return s(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="stairs-and-steps" tabindex="-1">Stairs and Steps <a class="header-anchor" href="#stairs-and-steps" aria-label="Permalink to &quot;Stairs and Steps&quot;">​</a></h1><p>How high a step RBQ can handle depends on the <strong>gait</strong> you use, on whether the stairs have <strong>risers</strong>, and on how <strong>deep</strong> the treads are compared with the step height. This page gives the limits for each gait and the conditions they hold under. The stair height on the <a href="/RBQ/nightly/manual/product-descriptions/general-specification.html">General Specifications</a> page holds only under these conditions.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>The heights on this page are for stairs that meet the conditions in <a href="#limits">Limits by gait</a>.</p></div></div><h2 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms {#terms}&quot;">​</a></h2><figure><img style="max-width:100%;width:min(420px, 100%);height:auto;display:block;margin:1rem auto;" src="'+e+'" alt="Stair dimensions: A step height, B tread depth"><figcaption style="text-align:center;">[ A step height · B tread depth ]</figcaption></figure><table tabindex="0"><thead><tr><th></th><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>A</td><td>Step height</td><td>Vertical distance from one tread to the next. A single curb or ledge counts as one step.</td></tr><tr><td>B</td><td>Tread depth</td><td>Horizontal depth of one tread, from its front edge to its back edge (the riser, if there is one).</td></tr><tr><td></td><td>Slope angle</td><td>How steep the stairs are, set by the step height (A) and the tread depth (B). Equal A and B give 45°.</td></tr><tr><td></td><td>Riser</td><td>The vertical board that closes the space between two treads.</td></tr><tr><td></td><td>Open-riser stairs</td><td>Stairs without risers, with open gaps between the treads. Grating stairs are one kind.</td></tr><tr><td></td><td>Grating stairs</td><td>Stairs whose treads are metal grating you can see through. They have no risers.</td></tr></tbody></table><h2 id="limits" tabindex="-1">Limits by gait <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits by gait {#limits}&quot;">​</a></h2><p>Maximum step height on the legged RBQ10.</p><table tabindex="0"><thead><tr><th>Gait</th><th>Stairs with risers</th><th>Open-riser stairs (grating and similar)</th></tr></thead><tbody><tr><td><code>STAIRS</code></td><td>Up to 20 cm</td><td>Up to 20 cm</td></tr><tr><td><code>RL_WALK</code> / <code>RL_WALK_VISION</code></td><td>Up to 25 cm</td><td>Not recommended</td></tr></tbody></table><ul><li>These heights are set for <strong>stairs whose tread depth (B) equals the step height (A), 1:1</strong>. Stairs with treads deeper than the step height (B &gt; A) can be used up to the same height. As a slope angle this is <strong>45° or less</strong>. Stairs with treads shallower than the step height (B &lt; A, over 45°) cannot be used.</li><li>On open-riser stairs choose <code>STAIRS</code>. <code>RL_WALK</code> and <code>RL_WALK_VISION</code> are not recommended there.</li><li>The 25 cm figure is for <code>RL_WALK_VISION</code> (<code>Vision Walk</code> on).</li></ul><h2 id="grating" tabindex="-1">Grating stairs <a class="header-anchor" href="#grating" aria-label="Permalink to &quot;Grating stairs {#grating}&quot;">​</a></h2><p>The <code>STAIRS</code> gait sees grating treads as steps with the depth cameras under the body. Grating stairs have no risers, so choose <code>STAIRS</code>; <code>RL_WALK</code> and <code>RL_WALK_VISION</code> are not recommended.</p><figure><img style="max-width:100%;width:min(420px, 100%);height:auto;display:block;margin:1rem auto;" src="'+a+'" alt="Top of a grating tread: openings 95 mm across and 25 mm deep, arrow shows the direction of travel"><figcaption style="text-align:center;">[ Largest grating opening: 95 mm across × 25 mm deep · arrow shows the direction of travel ]</figcaption></figure><ul><li>Grating with openings wider than 95 mm across × 25 mm deep is not recommended.</li><li>Step height and slope angle limits are the same as in <a href="#limits">Limits by gait</a>.</li></ul>',14)])])}const f=i(o,[["render",n]]);export{b as __pageData,f as default};
